316	}
317	import { cache } from "react";
318	import type { SupabaseClient } from "@supabase/supabase-js";
319	import { expenditurePosting, reportExpenditure, type ExpenditureRate } from "@/lib/finance/expenditure";
320	import { loadExpenditureRates } from "@/lib/finance/expenditure-rates";
321	
322	export type SpendingRow = Parameters<typeof expenditurePosting>[0] & { category_id: string | null; merchant_id: string | null };
323	type Total = { spendingMinor: bigint; partial: boolean };
324	
325	const day = (year: number, monthIndex: number, date: number) => new Date(Date.UTC(year, monthIndex, date)).toISOString().slice(0, 10);
326	const min = (a: string, b: string) => a < b ? a : b;
327	const MONTHS = 6;
328	const ROW_LIMIT = 50_000;
329	
330	// Totals come from reportExpenditure (exact-date FX, refunds subtracted, pending,
331	// transfers and review rows excluded). `partial` marks a total missing some rows.
332	function total(rows: SpendingRow[], rates: ExpenditureRate[], currencyCode: string, from: string, to: string): Total {
333	  const report = reportExpenditure(rows.map(expenditurePosting), rates, { view: "base", currencyCode, from, to });
334	  return { spendingMinor: BigInt(report.availableTotals.spendingMinor), partial: report.status === "incomplete" };
335	}
336	
337	export function summarizeSpending(rows: SpendingRow[], rates: ExpenditureRate[], currencyCode: string, today: string) {
338	  const [year, month, date] = today.split("-").map(Number);
339	  const trend = Array.from({ length: MONTHS }, (_, index) => {
340	    const offset = MONTHS - 1 - index;
341	    const from = day(year, month - 1 - offset, 1), to = min(day(year, month - offset, 0), today);
342	    return { month: from.slice(0, 7), from, to, ...total(rows, rates, currencyCode, from, to) };
343	  });
344	  const thisMonth = trend[MONTHS - 1];
345	  // Same number of days into last month, clamped to its end (31 Mar compares with 28/29 Feb).
346	  const lastFrom = day(year, month - 2, 1), lastTo = min(day(year, month - 2, date), day(year, month - 1, 0));
347	  const lastMonthToDate = { from: lastFrom, to: lastTo, ...total(rows, rates, currencyCode, lastFrom, lastTo) };
348	  const top = (key: "category_id" | "merchant_id", from: string, to: string) => {
349	    const current = rows.filter(row => row.posted_on >= from && row.posted_on <= to);
350	    const groups = new Map<string | null, SpendingRow[]>();
351	    for (const row of current) {
352	      const group = groups.get(row[key]);
353	      if (group) group.push(row); else groups.set(row[key], [row]);
354	    }
355	    return [...groups].map(([id, subset]) => ({ id, ...total(subset, rates, currencyCode, from, to) }))
356	      .filter(group => group.spendingMinor > 0n)
357	      .sort((a, b) => a.spendingMinor === b.spendingMinor ? 0 : a.spendingMinor < b.spendingMinor ? 1 : -1)
358	      .slice(0, 5);
359	  };
360	  // Top lists for every trend month, so Home can switch months without another read.
361	  const months = trend.map(({ month, from, to }) => ({ month, from, to, categories: top("category_id", from, to), merchants: top("merchant_id", from, to) }));
362	  const { categories, merchants } = months[MONTHS - 1];
363	  return { currencyCode, trend, thisMonth, lastMonthToDate, months, categories, merchants };
364	}
365	
366	// One read of the last six months feeds the KPI tile, trend chart and top lists; memoized per request.
367	export const loadHomeSpending = cache(async (db: SupabaseClient, workspaceId: string, currencyCode: string, today: string) => {
368	  const [year, month] = today.split("-").map(Number);
369	  const from = day(year, month - MONTHS, 1);
370	  async function loadRows() {
371	    const rows: SpendingRow[] = [];
372	    for (let offset = 0; ; offset += 1000) {
373	      const { data, error } = await db.from("effective_transactions")
374	        .select("id, parent_transaction_id, account_id, posted_on, version, amount_minor::text, currency_code, status, kind, review_reasons, category_id, merchant_id")
375	        .eq("workspace_id", workspaceId).gte("posted_on", from).lte("posted_on", today).order("id").range(offset, offset + 999);
376	      if (error) throw error;
377	      rows.push(...(data ?? []) as unknown as SpendingRow[]);
378	      if (rows.length > ROW_LIMIT) throw new Error("Spending history exceeds the Home summary limit");
379	      if (!data || data.length < 1000) return rows;
380	    }
381	  }
382	  const [rows, rates] = await Promise.all([loadRows(), loadExpenditureRates(db, workspaceId, { currencyCode, from, to: today })]);
383	  const summary = summarizeSpending(rows, rates, currencyCode, today);
384	  async function names(table: "categories" | "merchants", groups: { id: string | null }[]) {
385	    const ids = groups.flatMap(group => group.id ? [group.id] : []);
386	    if (!ids.length) return new Map<string, string>();
387	    const { data, error } = await db.from(table).select("id, name").eq("workspace_id", workspaceId).in("id", ids);
388	    if (error) throw error;
389	    return new Map((data ?? []).map(row => [row.id as string, row.name as string]));
390	  }
391	  const [categoryNames, merchantNames] = await Promise.all([names("categories", summary.months.flatMap(m => m.categories)), names("merchants", summary.months.flatMap(m => m.merchants))]);
392	  return { ...summary, categoryNames, merchantNames };
393	});
