import Link from "next/link";
import { AskAbout } from "@/components/ask-about";
import type { ReactNode } from "react";
import type { SupabaseClient } from "@supabase/supabase-js";
import { loadHomeSpending } from "@/lib/finance/dashboard-spending";
import { formatMoney } from "@/lib/finance/format";
import { minorDigits } from "@/lib/finance/fx";
import { TrendChart } from "./home-trend-chart";

type SectionProps = { db: SupabaseClient; workspaceId: string; currency: string; today: string; locale: string };

export const card = "min-w-0 rounded-xl border border-border bg-card p-6 sm:p-7";

/** One figure inside a card; stacked Kpis are divided by a hairline, as in the design. */
export function Kpi({ label, href, action, children }: { label: string; href?: string; action?: string; children: ReactNode }) {
  return <div className="min-w-0 border-t border-border pt-4 first:border-t-0 first:pt-0">
    <div className="flex items-baseline justify-between gap-2"><p className="text-sm text-muted-foreground">{label}</p>{href && <Link href={href} className="text-xs font-medium text-brand hover:underline">{action ?? "Details"}</Link>}</div>
    {children}
  </div>;
}

/** A formatted amount with its minor units dimmed, like the design's hero figures. */
export function Figure({ value, digits, className }: { value: string; digits: number; className?: string }) {
  const match = digits > 0 ? value.match(new RegExp(`^(.*\\d)([.,]\\d{${digits}})(\\D*)$`)) : null;
  return <p className={className}>{match ? <>{match[1]}<span className="text-[0.5em] tracking-tight text-subtle">{match[2]}</span>{match[3]}</> : value}</p>;
}

export function KpiFallback({ label }: { label: string }) {
  return <Kpi label={label}><p role="status" className="mt-2 h-8 w-32 animate-pulse rounded bg-muted"><span className="sr-only">Loading</span></p></Kpi>;
}

export function SectionFallback({ title }: { title: string }) {
  return <section aria-busy="true" className={card}><h2 className="text-sm font-medium">{title}</h2><p role="status" className="mt-3 text-sm text-muted-foreground">Loading…</p></section>;
}

const sign = (amount: bigint) => amount < 0n ? -amount : amount;

export async function MonthSpendingKpi({ db, workspaceId, currency, today, locale }: SectionProps) {
  let data;
  try { data = await loadHomeSpending(db, workspaceId, currency, today); } catch { data = null; }
  if (!data) return <Kpi label="Spent this month" href="/plan/spending"><p className="mt-2 text-sm text-muted-foreground">Spending is unavailable right now.</p></Kpi>;
  const { thisMonth, lastMonthToDate } = data;
  const change = thisMonth.spendingMinor - lastMonthToDate.spendingMinor;
  const percent = lastMonthToDate.spendingMinor > 0n ? Number(sign(change) * 100n / lastMonthToDate.spendingMinor) : null;
  return <Kpi label="Spent this month" href="/plan/spending" action="Plans">
    <p className="mt-1 font-mono text-xl">{formatMoney(thisMonth.spendingMinor, currency, locale)}{thisMonth.partial && <span className="ml-2 align-middle text-xs font-normal text-warning">Partial</span>}</p>
    <p className="mt-1 text-xs text-muted-foreground">vs {formatMoney(lastMonthToDate.spendingMinor, currency, locale)} by this day last month{lastMonthToDate.partial ? " (partial)" : ""}{percent !== null && change !== 0n ? ` · ${change > 0n ? "up" : "down"} ${percent}%` : ""}</p>
  </Kpi>;
}

function TopList({ title, groups, names, param, from, to, currency, locale, unknown }: {
  title: string; groups: { id: string | null; spendingMinor: bigint; partial: boolean }[]; names: Map<string, string>; param: "category" | "merchant"; from: string; to: string; currency: string; locale: string; unknown: string;
}) {
  const max = groups[0]?.spendingMinor ?? 0n;
  return <div className="min-w-0">
    <h3 className="text-sm font-semibold">{title}</h3>
    {groups.length ? <ul className="mt-2 space-y-1">{groups.map(group => <li key={group.id ?? "none"}>
      <Link href={`/money/transactions?${new URLSearchParams({ [param]: group.id ?? "none", from, to, direction: "outflow" })}`} className="group block rounded-md px-2 py-1.5 hover:bg-muted">
        <span className="flex justify-between gap-3 text-sm"><span className="truncate group-hover:underline">{group.id ? names.get(group.id) ?? unknown : unknown}</span><span className="shrink-0 font-mono">{formatMoney(group.spendingMinor, currency, locale)}{group.partial ? "*" : ""}</span></span>
        <span aria-hidden="true" className="mt-1 block h-1 rounded-full bg-muted"><span className="block h-1 rounded-full bg-brand" style={{ width: `${max > 0n ? Number(group.spendingMinor * 100n / max) : 0}%` }} /></span>
      </Link>
    </li>)}</ul> : <p className="mt-2 text-sm text-muted-foreground">No reviewed spending this month.</p>}
  </div>;
}

export async function SpendingPanel({ db, workspaceId, currency, today, locale, month: selectedMonth }: SectionProps & { month?: string }) {
  let data;
  try { data = await loadHomeSpending(db, workspaceId, currency, today); } catch { data = null; }
  const header = <div className="flex flex-wrap items-baseline justify-between gap-2"><h2 className="text-sm font-medium">Spending</h2><span className="flex items-center gap-3"><AskAbout question="Why did my spending change over the last six months? Which categories and merchants drove it?" about={{ kind: "chart", label: "Six-month spending trend" }} /><Link href="/money/transactions?direction=outflow" className="text-sm font-medium text-brand hover:underline">All spending</Link></span></div>;
  if (!data) return <section aria-label="Spending" className={card}>{header}<p role="alert" className="mt-3 text-sm">Spending is unavailable right now. Your balances are not affected.</p></section>;
  const month = new Intl.DateTimeFormat(locale, { month: "short", timeZone: "UTC" });
  const scale = 10 ** minorDigits(currency);
  const selected = data.months.find(row => row.month === selectedMonth) ?? data.months[data.months.length - 1];
  const bars = data.trend.filter(row => row.spendingMinor > 0n);
  const label = selected.month === data.thisMonth.month ? "this month" : `in ${new Intl.DateTimeFormat(locale, { month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${selected.from}T00:00:00Z`))}`;
  const partial = data.trend.some(row => row.partial) || selected.categories.some(row => row.partial);
  return <section aria-label="Spending" className={card}>
    {header}
    <p className="mt-1 text-xs text-muted-foreground">Last six months in {currency}. Refunds are subtracted; pending items, transfers and items needing review are left out.</p>
    <div className="mt-3"><TrendChart height={200} months={bars.map(row => row.month)} labels={bars.map(row => month.format(new Date(`${row.from}T00:00:00Z`)))} values={bars.map(row => Number(row.spendingMinor) / scale)} /></div>
    {partial && <p className="mt-2 text-xs text-warning">* Partial: some rows need review or an exchange rate for their posting date.</p>}
    <div className="mt-4 grid gap-6 md:grid-cols-2">
      <TopList title={`Top categories ${label}`} groups={selected.categories} names={data.categoryNames} param="category" from={selected.from} to={selected.to} currency={currency} locale={locale} unknown="Uncategorized" />
      <TopList title={`Top merchants ${label}`} groups={selected.merchants} names={data.merchantNames} param="merchant" from={selected.from} to={selected.to} currency={currency} locale={locale} unknown="Unknown merchant" />
    </div>
  </section>;
}

export async function RecentTransactions({ db, workspaceId, locale, names }: Omit<SectionProps, "currency" | "today"> & { names: Map<string, string> }) {
  const { data, count, error } = await db.from("transactions").select("id, posted_on, description, amount_minor::text, currency_code, status, account_id, review_reasons", { count: "exact" })
    .eq("workspace_id", workspaceId).order("posted_on", { ascending: false }).order("id").limit(8);
  const rows = (data ?? []) as { id: string; posted_on: string; description: string | null; amount_minor: string; currency_code: string; status: string; account_id: string; review_reasons: string[] | null }[];
  return <section aria-label="Recent transactions" className={card}>
    <div className="flex items-baseline justify-between gap-2"><h2 className="text-sm font-medium">Recent transactions</h2><Link href="/money/transactions" className="text-sm font-medium text-brand hover:underline">All {count ?? 0}</Link></div>
    {error ? <p role="alert" className="mt-3 text-sm">Recent transactions are unavailable right now.</p>
      : rows.length ? <ul className="mt-2 divide-y divide-border">{rows.map(row => <li key={row.id}>
        <Link href={`/money/transactions?transaction=${row.id}`} className="flex items-center gap-3 py-2 text-sm hover:bg-muted">
          <span className="w-20 shrink-0 font-mono text-xs text-muted-foreground">{row.posted_on}</span>
          <span className="min-w-0 flex-1"><span className="block truncate">{row.description ?? "Recorded posting"}</span><span className="block truncate text-xs text-muted-foreground">{names.get(row.account_id) ?? "Account"}{row.status === "pending" ? " · pending" : ""}{row.review_reasons?.length ? " · needs review" : ""}</span></span>
          <span className="shrink-0 font-mono">{formatMoney(row.amount_minor, row.currency_code, locale)}</span>
        </Link>
      </li>)}</ul>
      : <p className="mt-3 text-sm text-muted-foreground">No transactions yet. <Link href="/import" className="text-brand underline">Import a statement</Link>.</p>}
  </section>;
}
"use client";
import dynamic from "next/dynamic";
import { usePathname, useRouter, useSearchParams } from "next/navigation";

// Client-only and lazy so echarts stays out of Home's initial bundle.
const Chart = dynamic(() => import("@/components/chart").then(module => module.SpendingChart), {
  ssr: false, loading: () => <div aria-hidden="true" className="h-[200px] animate-pulse rounded-lg bg-muted" />,
});

// Clicking a month bar sets ?month= so the server re-renders the top lists for it.
export function TrendChart({ months, ...props }: { months: string[]; labels: string[]; values: number[]; height: number }) {
  const router = useRouter(), pathname = usePathname(), params = useSearchParams();
  return <Chart {...props} onSelect={index => {
    const next = new URLSearchParams(params);
    next.set("month", months[index]);
    router.replace(`${pathname}?${next}`, { scroll: false });
  }} />;
}
import {formatMoney} from "@/lib/finance/format";
import type {resolveBalances} from "@/lib/finance/balances";
import {wealthEvidence, type WealthValue} from "@/lib/finance/wealth";

export function DatedOverview({accounts, wealth, today, locale}: {
  accounts: ReturnType<typeof resolveBalances>; wealth: WealthValue[]; today: string; locale: string;
}) {
  const valuations = wealthEvidence(wealth, today, "observed");
  const observations = accounts.filter(account => !account.archived_at && account.balance.snapshot_valid && account.balance.snapshot_amount_minor !== null)
    .map(account => ({id: `account:${account.id}`, name: account.name, amount: BigInt(account.balance.snapshot_amount_minor!),
      currency: account.balance.snapshot_currency_code!}));
  observations.push(...valuations.included.map(value => ({id: `wealth:${value.id}`, name: value.name, amount: value.amountMinor,
    currency: value.currencyCode})));
  const totals = new Map<string, bigint>();
  for (const observation of observations) totals.set(observation.currency, (totals.get(observation.currency) ?? 0n) + observation.amount);
  return <details className="border-t border-border pt-3 text-sm">
    <summary className="cursor-pointer text-xs font-medium text-muted-foreground hover:text-foreground">Recorded net worth by currency</summary>
    <ul className="mt-3 space-y-1">{[...totals].map(([currency, amount]) => <li key={currency} className="font-mono font-semibold">{formatMoney(amount, currency, locale)}</li>)}</ul>
    <ul className="mt-3 divide-y divide-border">{observations.map(row => <li key={row.id} className="flex justify-between gap-3 py-2"><span className="truncate">{row.name}</span><span className="shrink-0 font-mono">{formatMoney(row.amount, row.currency, locale)}</span></li>)}</ul>
  </details>;
}
import Link from "next/link";
import type { SupabaseClient } from "@supabase/supabase-js";
import { LoaderCircle, Sparkle } from "lucide-react";
import { StartAgentRun } from "./ai/agents/start-run";

/** Home's proactive briefing: the latest agent-team run, what it found and what waits for review. */
export async function AgentBriefing({ db, workspaceId }: { db: SupabaseClient; workspaceId: string }) {
  const latest = await db.from("agent_runs").select("id, status, briefing, created_at").eq("workspace_id", workspaceId).order("created_at", { ascending: false }).limit(1).maybeSingle();
  if (latest.error) return null;
  const run = latest.data;
  const open = run ? await db.from("agent_proposals").select("kind").eq("workspace_id", workspaceId).eq("run_id", run.id).eq("status", "proposed").limit(500) : null;
  const findings = open?.data?.filter(item => item.kind === "finding").length ?? 0, changes = (open?.data?.length ?? 0) - findings;
  const running = run && ["queued", "running"].includes(run.status);
  return <section aria-label="Agent briefing" className="flex flex-wrap items-start gap-4 rounded-xl border border-ai-border bg-ai-soft px-6 py-5">
    <Sparkle className="mt-0.5 size-4 shrink-0 fill-current text-ai" aria-hidden="true" />
    <div className="min-w-0 flex-1">
      <h2 className="text-sm font-medium text-ai">{running ? "Your agent team is working" : run?.briefing ? "Briefing from your agent team" : "Agent team"}</h2>
      {running ? <p className="mt-1 flex items-center gap-2 text-sm text-muted-foreground"><LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />Analysing your latest data. <Link href={`/ai/agents/${run.id}`} className="text-brand underline">Watch live</Link></p>
        : run?.briefing ? <p className="mt-1.5 line-clamp-3 text-[15px] leading-relaxed text-pretty">{run.briefing.split(/\n{2,}/)[0]}</p>
        : <p className="mt-1 text-sm text-muted-foreground">Seven specialised agents categorize, find subscriptions and anomalies, forecast cash and propose limits. They run after every import, or now.</p>}
      {run && !running && (findings > 0 || changes > 0) && <p className="mt-2 text-xs"><Link href={`/ai/agents/${run.id}`} className="ai-chip">{[changes && `${changes} changes to review`, findings && `${findings} findings`].filter(Boolean).join(" · ")}</Link></p>}
    </div>
    {!running && <StartAgentRun label={run ? "Run again" : "Run agent team"} className="inline-flex h-10 items-center gap-2 rounded-xl bg-ai px-4 text-[13px] font-medium text-[#0f1011] hover:opacity-90 disabled:opacity-50" />}
  </section>;
}
import Link from "next/link";
import { cache } from "react";
import type { SupabaseClient } from "@supabase/supabase-js";
import { buildInsights, insightPreferencesSchema, defaultInsightPreferences, type InsightInput } from "@/lib/finance/insights";
import { describeMissingInputs } from "@/lib/finance/format";
import { type ReviewTransaction } from "@/lib/finance/review";
import { budgetProgress, type MonthlyLimit } from "@/lib/finance/spending-plans";
import { type WorkspaceSettings } from "@/lib/settings";
import type { evaluatePlan } from "@/lib/finance/model";
import { dismissInsight } from "./actions";
import { buildSourceCoverage, loadSourceCoverageMetadata, sourceCoverageNeedsReview } from "@/lib/finance/source-coverage";

const card = "min-w-0 rounded-xl border border-border bg-card p-5";

type Projection = Awaited<ReturnType<typeof evaluatePlan>>;
type Budget = { id: string; category_id: string; currency_code: string; limit_minor: string; enabled: boolean; rollover: boolean; rollover_from: string };
type Goal = { id: string; name: string; target_minor: string; recorded_saved_minor: string | null; saved_as_of: string | null; status: string };
type Recurring = { id: string; label: string; evidence_invalidated: boolean; evidence_baseline: { id: string }[] | null; invalidated_assumption_version: number | null };
type Wealth = { id: string; name: string; kind: string; amount_minor: string; currency_code: string; as_of: string; removed_at?: string | null };

type InsightPanelProps = {
  db: SupabaseClient; workspaceId: string; currency: string; today: string; settings: WorkspaceSettings; projection: Projection; missingInputs: string[]; names?: Map<string, string>; wealth: Wealth[];
};
// Database reads only, memoized per request so Home can start them before its own data
// resolves; nothing here depends on the projection. Independent reads load together.
export const loadInsightEvidence = cache(async (db: SupabaseClient, workspaceId: string, currency: string, today: string) => {
    async function rows<T>(table: string, columns: string, start?: string): Promise<T[]> {
      const collected: T[] = [];
      for (let offset = 0; offset <= 10000; offset += 500) {
        let query = db.from(table).select(columns).eq("workspace_id", workspaceId);
        if (start) query = query.gte("posted_on", start).lte("posted_on", today);
        const result = await query.order(table === "insight_dismissals" ? "evidence_key" : "id").range(offset, offset + 499);
        if (result.error) throw result.error;
        if (offset === 10000 && result.data.length) throw new Error("Insight evidence exceeds the supported 10,000-row limit");
        collected.push(...result.data as T[]);
        if (result.data.length < 500) return collected;
      }
      return collected;
    }
    async function byIds<T>(columns: string, ids: string[]) {
      const pages = await Promise.all(Array.from({ length: Math.ceil(ids.length / 100) }, async (_, index) => {
        const page = await db.from("transactions").select(columns).eq("workspace_id", workspaceId).in("id", ids.slice(index * 100, index * 100 + 100));
        if (page.error) throw page.error;
        return page.data as unknown as T[];
      }));
      return pages.flat();
    }
    const recentStart = new Date(Date.parse(`${today}T00:00:00Z`) - 90 * 86400000).toISOString().slice(0, 10);
    const columns = "id,parent_transaction_id,account_id,description,amount_minor::text,currency_code,status,kind,review_reasons,posted_on,category_id,merchant_id,refund_of_id";
    const canonicalColumns = columns.replace("parent_transaction_id,", "");
    const [pref, budgets, categories, goals, recurring, limits, dismissals, canonical, sourceMetadata] = await Promise.all([
      db.from("insight_preferences").select("important_only,minimum_change_minor::text,currency_code,upcoming_days,max_items").eq("workspace_id", workspaceId).maybeSingle(),
      rows<Budget>("spending_plans", "id,category_id,currency_code,limit_minor::text,enabled,rollover,rollover_from"), rows<{ id: string; name: string }>("categories", "id,name"),
      rows<Goal>("goals", "id,name,target_minor::text,recorded_saved_minor::text,saved_as_of,status"),
      rows<Recurring>("recurring_series", "id,label,evidence_invalidated,evidence_baseline,invalidated_assumption_version"),
      rows<MonthlyLimit & { id: string; plan_id: string }>("spending_plan_limits", "id,plan_id,effective_month,limit_minor::text,enabled,version"),
      rows<{ evidence_key: string }>("insight_dismissals", "evidence_key"),
      rows<ReviewTransaction & { account_id: string }>("transactions", canonicalColumns, recentStart),
      loadSourceCoverageMetadata(db, workspaceId, true),
    ]);
    if (pref.error) throw pref.error;
    const preferences = insightPreferencesSchema.parse(pref.data ?? defaultInsightPreferences(currency));
    const first = budgets.filter(budget => budget.enabled && budget.rollover).reduce((start, budget) => budget.rollover_from < start ? budget.rollover_from : start, recentStart);
    const recurringEvidence = new Map(canonical.map(row => [row.id, row]));
    const missingBaselineIds = [...new Set(recurring.flatMap(series => (series.evidence_baseline ?? []).map(row => row.id)))].filter(id => !recurringEvidence.has(id));
    if (missingBaselineIds.length > 10000) throw new Error("Recurring insight evidence exceeds the current bound");
    const [transactions, older] = await Promise.all([
      rows<ReviewTransaction & { account_id: string }>("effective_transactions", columns, first),
      byIds<ReviewTransaction & { account_id: string }>(canonicalColumns, missingBaselineIds),
    ]);
    for (const row of older) recurringEvidence.set(row.id, row);
    const refundIds = [...new Set(transactions.flatMap(row => row.refund_of_id ? [row.refund_of_id] : []))];
    const originals = await byIds<{ id: string; category_id: string | null }>("id,category_id", refundIds);
    for (const row of transactions) if (row.refund_of_id) row.refund_category_id = originals.find(original => original.id === row.refund_of_id)?.category_id ?? row.refund_category_id;
    return { preferences, budgets, categories, goals, recurring, limits, dismissals, canonical, sourceMetadata, first, transactions, recurringEvidence };
});

async function loadInsights({ db, workspaceId, currency, today, settings, projection, missingInputs, names, wealth }: InsightPanelProps) {
    const { preferences, budgets, categories, goals, recurring, limits, dismissals, canonical, sourceMetadata, first, transactions, recurringEvidence } = await loadInsightEvidence(db, workspaceId, currency, today);
    const sourceCoverage = buildSourceCoverage({ from: first, to: today }, transactions, sourceMetadata?.imports, sourceMetadata?.sources);
    const warnings = describeMissingInputs([...missingInputs, ...(projection.input.missingInputs ?? [])], names);
    if (transactions.some(row => row.status === "posted" && row.review_reasons?.length)) warnings.push("Some financial classifications need review; comparisons omit uncertain rows");
    const spendingRows = transactions.map(row => ({ amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code, status: row.status, kind: row.kind, reviewReasons: row.review_reasons, postedOn: row.posted_on, categoryId: row.category_id,
      ...(row.refund_of_id ? { refundOfCategoryId: row.refund_category_id ?? null } : {}) }));
    const budgetEvidence: InsightInput["budgets"] = [];
    for (const budget of budgets.filter(budget => budget.enabled)) {
      const budgetCoverage = buildSourceCoverage({ from: budget.rollover ? budget.rollover_from : `${today.slice(0, 7)}-01`, to: today, currencyCode: budget.currency_code }, transactions, sourceMetadata?.imports, sourceMetadata?.sources);
      const progress = budgetProgress(spendingRows, budget.category_id, budget.currency_code, today.slice(0, 7), BigInt(budget.limit_minor), budget.rollover ? { startsMonth: budget.rollover_from.slice(0, 7), history: limits.filter(limit => limit.plan_id === budget.id) } : undefined, budgetCoverage);
      if (progress.allowanceMinor === null) { if (progress.limitation) warnings.push(progress.limitation); continue; }
      budgetEvidence.push({ id: budget.id, name: categories.find(category => category.id === budget.category_id)?.name ?? "Category", currency: budget.currency_code,
        spentMinor: progress.spentMinor.toString(), allowanceMinor: progress.allowanceMinor.toString(), partial: progress.partial, sourceCoverage: budgetCoverage });
    }
    const events = projection.input.events.filter(event => event.source !== "estimated" && event.expectedMinor < 0n);
    const obligations = new Map<string, InsightInput["obligations"][number]>();
    for (const event of events) {
      const id = `${event.accountId}:${event.date}`, previous = obligations.get(id);
      obligations.set(id, { id, name: "Confirmed payments", date: event.date, amountMinor: ((previous ? BigInt(previous.amountMinor) : 0n) + event.expectedMinor).toString(), currency });
    }
    const insights = buildInsights({ today, currency, locale: settings.locale, transactions, canonicalTransactions: canonical, categories, budgets: budgetEvidence, sourceCoverage, forecastSourceCoverage: projection.sourceCoverage,
      recurring: recurring.map(series => ({ ...series, evidence: [series.invalidated_assumption_version, series.evidence_baseline, (series.evidence_baseline ?? []).map(row => recurringEvidence.get(row.id) ?? null)] })),
      obligations: [...obligations.values()],
      goals: goals.filter(goal => goal.status === "active").map(goal => ({ id: goal.id, name: goal.name, targetMinor: goal.target_minor, savedMinor: goal.recorded_saved_minor, savedAsOf: goal.saved_as_of })),
      wealth: wealth.filter(item => !item.removed_at).map(item => ({ id: item.id, name: item.name, kind: item.kind, amountMinor: item.amount_minor, currency: item.currency_code, asOf: item.as_of })),
      missingInputs: warnings, available: projection.available.status === "available" ? { amountMinor: projection.available.amountMinor.toString(), limitingDate: projection.available.limitingDate } : null,
    }, preferences, settings.muted_insight_types, dismissals.map(dismissal => dismissal.evidence_key));
    return insights;
}

export async function ImportantInsights(props: InsightPanelProps) {
  let insights: Awaited<ReturnType<typeof loadInsights>> | null = null;
  try { insights = await loadInsights(props); } catch { insights = null; }
  const header = <div className="flex items-baseline justify-between gap-2"><h2 className="text-sm font-medium">Important insights</h2><Link href="/settings" className="text-sm text-muted-foreground hover:text-foreground hover:underline">Customize</Link></div>;
  if (insights === null) return <section className={card}>{header}<p role="alert" className="mt-3 text-sm">Insights are unavailable right now. Your totals elsewhere are not affected.</p><Link href="/import" className="mt-3 inline-block text-sm font-medium text-brand hover:underline">Review imports</Link></section>;
  return <section className={card}>{header}
    <ul className="mt-2 divide-y divide-border">
      {insights.map(insight => <li key={insight.key} className="flex items-start gap-3 py-2">
        <div className="min-w-0 flex-1">
          <Link className="block truncate text-sm font-medium hover:underline" href={insight.href}>{insight.title}</Link>
          <p className="line-clamp-2 text-xs text-muted-foreground" title={insight.detail}><span className="capitalize">{insight.type.replaceAll("_", " ")}</span>{sourceCoverageNeedsReview(insight.sourceCoverage) ? " · sources incomplete" : ""} · {insight.detail}</p>
        </div>
        <form action={dismissInsight}><input type="hidden" name="key" value={insight.key} /><input type="hidden" name="type" value={insight.type} /><button className="rounded px-1.5 text-sm text-muted-foreground hover:bg-muted hover:text-foreground" aria-label={`Dismiss ${insight.title}`} title="Dismiss">×</button></form>
      </li>)}
    </ul>{!insights.length ? <p className="mt-3 text-sm text-muted-foreground">Nothing to flag right now.</p> : null}</section>;
}import { z } from "zod";

// Key order is the default Home order. Keys are stored in saved layouts; never rename one.
export const BUILTIN_WIDGETS = { overview: "Overview", spending: "Spending trend, categories and merchants", recent: "Recent transactions", insights: "Important insights",
  upcoming: "Upcoming payments", planning: "Available funds by account", accounts: "Accounts", goals: "Goals" };
// Artifacts pinned to Home are stored as "artifact:<uuid>" next to the built-in keys.
const ARTIFACT_KEY = /^artifact:([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/;
const isWidgetKey = (key: string) => Object.hasOwn(BUILTIN_WIDGETS, key) || ARTIFACT_KEY.test(key);
