"use client";

import { Component, useMemo, useSyncExternalStore, type ReactNode } from "react";
import dynamic from "next/dynamic";

// Loaded on the client only, so echarts never ships in the server render or blocks first paint.
const ReactECharts = dynamic(() => import("echarts-for-react"), { ssr: false });

function subscribeTheme(onChange: () => void) {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  return () => observer.disconnect();
}

/** Resolves a color token to a concrete color; tokens are light-dark() pairs, which ECharts cannot parse. */
function token(name: string, fallback: string) {
  if (typeof document === "undefined") return fallback;
  const probe = document.createElement("span");
  probe.style.color = `var(${name})`;
  document.body.appendChild(probe);
  const color = getComputedStyle(probe).color;
  probe.remove();
  return color || fallback;
}

// Chart colors follow the app's CSS tokens, including the dark theme.
function useThemeColors() {
  const theme = useSyncExternalStore(subscribeTheme, () => document.documentElement.dataset.theme ?? "light", () => "light");
  return useMemo(() => {
    const fallback = theme === "dark" ? { brand: "#cbf26b", muted: "#a3a39e", border: "#24262a" } : { brand: "#4a6400", muted: "#5c5d58", border: "#e2e0d8" };
    return { brand: token("--color-brand", fallback.brand), muted: token("--color-muted-foreground", fallback.muted), border: token("--color-border", fallback.border) };
  }, [theme]);
}

export function SpendingChart({ values, labels, type = "bar", height = 280, ariaLabel, formatValue, onSelect }: {
  values: number[];
  labels?: string[];
  type?: "bar" | "line";
  height?: number;
  ariaLabel?: string;
  formatValue?: (value: number) => string;
  onSelect?: (index: number) => void;
}) {
  const colors = useThemeColors();
  const axis = { axisLine: { lineStyle: { color: colors.border } }, axisLabel: { color: colors.muted }, splitLine: { lineStyle: { color: colors.border, type: "dashed" } } };
  return (
    <div role={ariaLabel ? "img" : undefined} aria-label={ariaLabel}>
      <ReactECharts
        option={{
          color: [colors.brand],
          grid: { left: 8, right: 8, top: 16, bottom: 8, containLabel: true },
          tooltip: { trigger: "axis", ...(formatValue ? { valueFormatter: formatValue } : {}) },
          xAxis: { type: "category", data: labels ?? values.map((_, i) => `W${i + 1}`), ...axis },
          yAxis: { type: "value", ...axis, ...(formatValue ? { axisLabel: { color: colors.muted, formatter: formatValue } } : {}) },
          series: [{ type, data: values, ...(type === "line" ? { smooth: true, showSymbol: false, areaStyle: { opacity: 0.12 } } : { barMaxWidth: 28, itemStyle: { borderRadius: [4, 4, 4, 4] } }) }],
        }}
        style={{ height, cursor: onSelect ? "pointer" : undefined }}
        onEvents={onSelect ? { click: (event: { dataIndex: number }) => onSelect(event.dataIndex) } : undefined}
      />
    </div>
  );
}

type ForecastChartDay = { date: string; expected: number; conservative: number; optimistic: number };
type ForecastChartObligation = { date: string; name: string; amount: string };

// Approximate chart coordinates (major units as numbers); exact amounts are rendered by the caller.
export function ForecastChart({ days, obligations, currency, label, compare }: {
  days: ForecastChartDay[]; obligations: ForecastChartObligation[]; currency: string; label: string;
  /** Optional second expected line, e.g. the real plan while a what-if scenario is shown. */
import { expect, it } from "vitest";
import { summarizeSpending, type SpendingRow } from "@/lib/finance/dashboard-spending";

const row = (id: string, posted_on: string, amount_minor: string, extra: Partial<SpendingRow> = {}): SpendingRow => ({
  id, account_id: "a", posted_on, amount_minor, currency_code: "EUR", status: "posted", kind: "ordinary", review_reasons: [], category_id: "food", merchant_id: "shop", ...extra });

it("compares month-to-date with the same days last month and ranks categories and merchants from reported totals", () => {
  const summary = summarizeSpending([
    row("1", "2026-03-31", "-500"),
    row("2", "2026-02-28", "-300"),
    row("3", "2026-02-27", "-100", { category_id: null, merchant_id: null }),
    row("4", "2026-03-02", "-200", { category_id: "rent", merchant_id: "landlord" }),
    row("5", "2026-03-03", "150", { kind: "refund" }),
    row("6", "2026-03-04", "-999", { status: "pending" }),
    row("7", "2026-03-05", "-999", { kind: "transfer" }),
    row("8", "2026-03-06", "-50", { currency_code: "USD", merchant_id: "abroad" }),
    row("9", "2025-10-01", "-70"),
  ], [], "EUR", "2026-03-31");
  expect(summary.trend.map(month => month.month)).toEqual(["2025-10", "2025-11", "2025-12", "2026-01", "2026-02", "2026-03"]);
  expect(summary.trend.map(month => month.spendingMinor)).toEqual([70n, 0n, 0n, 0n, 400n, 550n]);
  expect(summary.thisMonth).toMatchObject({ spendingMinor: 550n, partial: true });
  expect(summary.lastMonthToDate).toMatchObject({ from: "2026-02-01", to: "2026-02-28", spendingMinor: 400n, partial: false });
  expect(summary.categories.map(group => [group.id, group.spendingMinor])).toEqual([["food", 350n], ["rent", 200n]]);
  expect(summary.merchants.map(group => [group.id, group.spendingMinor])).toEqual([["shop", 350n], ["landlord", 200n]]);
});

