import { renderToStaticMarkup } from "react-dom/server";
import type { SupabaseClient } from "@supabase/supabase-js";
import { expect, it, vi } from "vitest";
import { MonthSpendingKpi, RecentTransactions, SpendingPanel } from "./home-sections";

vi.mock("next/link", () => ({ default: "a" }));
vi.mock("./home-trend-chart", () => ({ TrendChart: ({ labels }: { labels: string[] }) => <div data-chart={labels.join(",")} /> }));
vi.mock("@/lib/finance/dashboard-spending", async original => {
  const actual = await original<typeof import("@/lib/finance/dashboard-spending")>();
  const row = { account_id: "a", currency_code: "EUR", status: "posted", kind: "ordinary", review_reasons: [] };
  const summary = actual.summarizeSpending([
    { ...row, id: "1", posted_on: "2026-10-02", amount_minor: "-4000", category_id: "food", merchant_id: null },
    { ...row, id: "2", posted_on: "2026-09-02", amount_minor: "-2000", category_id: "food", merchant_id: "shop" },
  ], [], "EUR", "2026-10-16");
  return { ...actual, loadHomeSpending: async () => ({ ...summary, categoryNames: new Map([["food", "Food"]]), merchantNames: new Map() }) };
});
const props = { db: {} as SupabaseClient, workspaceId: "w", currency: "EUR", today: "2026-10-16", locale: "en" };

it("links top categories and merchants to filtered transactions and compares with the same days last month", async () => {
  const html = renderToStaticMarkup(await SpendingPanel(props));
  expect(html).toContain('data-chart="Sep,Oct"');
  expect(html).toContain("Food");
  expect(html).toContain("/money/transactions?category=food&amp;from=2026-10-01&amp;to=2026-10-16&amp;direction=outflow");
  expect(html).toContain("Unknown merchant");
  expect(html).toContain("merchant=none");
  const september = renderToStaticMarkup(await SpendingPanel({ ...props, month: "2026-09" }));
  expect(september).toContain("Top merchants in September 2026");
  expect(september).toContain("merchant=shop&amp;from=2026-09-01&amp;to=2026-09-30");
  const kpi = renderToStaticMarkup(await MonthSpendingKpi(props));
  expect(kpi).toContain("EUR 40.00"); expect(kpi).toContain("vs EUR 20.00 by this day last month"); expect(kpi).toContain("up 100%");
});

it("lists recent ledger entries with account names, status and the total count", async () => {
  const rows = [{ id: "t1", posted_on: "2026-10-15", description: "Coffee", amount_minor: "-350", currency_code: "EUR", status: "pending", account_id: "a", review_reasons: [] }];
  const query = { select: () => query, eq: () => query, order: () => query, limit: async () => ({ data: rows, count: 42, error: null }) };
  const html = renderToStaticMarkup(await RecentTransactions({ db: { from: () => query } as unknown as SupabaseClient, workspaceId: "w", locale: "en", names: new Map([["a", "Checking"]]) }));
  for (const text of ["All 42", "Coffee", "Checking · pending", "-EUR 3.50", "/money/transactions?transaction=t1"]) expect(html).toContain(text);
});
import { buildSourceCoverage } from "@/lib/finance/source-coverage";
import { beforeEach, expect, it, vi } from "vitest";
import { renderToStaticMarkup } from "react-dom/server";
import Home from "./page";
vi.mock("./agent-briefing", () => ({ AgentBriefing: () => null }));
vi.mock("./insights/panel", () => ({ ImportantInsights: () => null, loadInsightEvidence: async () => ({}) }));
const fixture = vi.hoisted(() => ({ started: [] as string[], errorTable: "", balanceGate: null as Promise<void> | null }));
beforeEach(() => { fixture.started = []; fixture.errorTable = ""; fixture.balanceGate = null; });

vi.mock("@/lib/env", () => ({ hasSupabase: () => true, getSupabaseConfig: () => ({ status: "configured", detail: "Supabase configuration is present." }) }));
vi.mock("@/lib/auth", () => ({ requireWorkspace: async () => {
  return { supabase: { from: (table: string) => {
    const result = () => { fixture.started.push(table); return { data: [], count: 0, error: fixture.errorTable === table ? new Error(`${table} unavailable`) : null }; };
    const query = { select: () => query, eq: () => query, in: () => query, is: () => query, range: async () => result(), order: () => query, limit: () => query, maybeSingle: async () => ({ ...result(), data: null }), then: (resolve: (value: unknown) => unknown) => Promise.resolve(result()).then(resolve) };
    return query;
  } }, workspace: { id: "workspace", display_currency: "EUR", timezone: "Europe/Berlin" } };
} }));
vi.mock("@/lib/finance/balances", async importOriginal => ({ ...await importOriginal<typeof import("@/lib/finance/balances")>(), loadBalanceEvidence: async () => { await fixture.balanceGate; return { accounts: [{ id: "cash", name: "Empty cash", currency_code: "EUR" }], snapshots: [], ledger: [], asOf: "2026-10-01T12:00:00Z" }; } }));
vi.mock("@/lib/finance/model", () => ({ evaluatePlanForWorkspace: async () => ({ sourceCoverage: buildSourceCoverage({ from: "2026-10-01", to: "2026-10-07" }, []), available: { status: "unavailable", missingInputs: ["balance:cash"] }, liquidity: { status: "unavailable", missingInputs: ["balance:cash"] } }) }));
vi.mock("@/lib/finance/tools", () => ({ cashflow: async () => ({ sourceCoverage: buildSourceCoverage({ from: "2026-10-01", to: "2026-10-07" }, []), unavailable: "No transactions" }) }));
vi.mock("next/link", () => ({ default: ({ children, href }: { children: React.ReactNode; href: string }) => <a href={href}>{children}</a> }));

it("shows a missing balance without inventing an epoch date or provenance", async () => {
  const html = renderToStaticMarkup(await Home());
  expect(html).toContain("Balance unknown");
  expect(html).toContain("Add a dated balance");
  expect(html).toContain("<summary class=\"cursor-pointer text-xs font-medium text-brand hover:underline\">Update balance</summary>");
  for (const text of ["Net worth", "Cash available", "Spent this month", "Upcoming payments"]) expect(html).toContain(text);
  expect(html).not.toContain("1970");
  expect(html).not.toContain("null · as of");
});

it("starts independent dashboard queries while balance evidence is still loading", async () => {
  let release!: () => void;
  fixture.balanceGate = new Promise(resolve => { release = resolve; });
  const page = Home();
  await new Promise(resolve => setTimeout(resolve, 0));
  const started = [...fixture.started];
  release();
  await page;

