// Seeds the QA user's workspace with six months of demo data for eyeballing Home. Undo with: node --env-file=.env scripts/e2e-auth.mjs --reset
import postgres from "postgres";
const db = postgres(process.env.SUPABASE_DB_URL, { ssl: "require", max: 1 });
const [{ id: workspace }] = await db`select w.id from public.workspaces w join auth.users u on u.id = w.owner_id where u.email = ${process.env.E2E_USER_EMAIL}`;
const today = new Date().toISOString().slice(0, 10);
const day = (monthsBack, date) => { const d = new Date(Date.UTC(+today.slice(0, 4), +today.slice(5, 7) - 1 - monthsBack, date)); return d.toISOString().slice(0, 10); };
await db.begin(async tx => {
  const [main] = await tx`insert into public.accounts(workspace_id,name,currency_code,type) values(${workspace},'N26 Main','EUR','checking') returning id`;
  const [savings] = await tx`insert into public.accounts(workspace_id,name,currency_code,type) values(${workspace},'Sparkasse Tagesgeld','EUR','savings') returning id`;
  const cats = {}; for (const name of ["Salary", "Groceries", "Eating out", "Transport", "Rent", "Going out"]) [cats[name]] = await tx`insert into public.categories(workspace_id,name) values(${workspace},${name}) returning id`;
  const merch = {}; for (const name of ["Acme GmbH", "Rewe", "Lidl", "Vapiano", "BVG", "Landlord", "Freelance client"]) [merch[name]] = await tx`insert into public.merchants(workspace_id,name,normalized_name) values(${workspace},${name},${name.toLowerCase()}) returning id`;
  const rows = [];
  for (let m = 5; m >= 0; m--) {
    const add = (date, description, amount, cat, mer) => { const posted = day(m, date); if (posted <= today) rows.push({ posted, description, amount, cat: cats[cat].id, mer: merch[mer].id }); };
    add(1, "Salary Acme", 420000 + m * 1000, "Salary", "Acme GmbH");
    if (m % 2 === 0) add(14, "Invoice 42", 60000, "Salary", "Freelance client");
    add(1, "Rent", -115000, "Rent", "Landlord");
    for (const date of [3, 9, 16, 23]) add(date, "Rewe", -(8000 + m * 900 + date * 50), "Groceries", "Rewe");
    add(12, "Lidl", -4200, "Groceries", "Lidl");
    for (const date of [6, 13, 20]) add(date, "Vapiano", -(5200 + m * 300), "Eating out", "Vapiano");
    add(2, "BVG monthly", -5800, "Transport", "BVG");
    add(18, "Cinema", -3200, "Going out", "Vapiano");
  }
  for (const row of rows) await tx`insert into public.transactions(workspace_id,account_id,posted_on,description,amount_minor,currency_code,status,category_id,merchant_id) values(${workspace},${main.id},${row.posted},${row.description},${row.amount},'EUR','posted',${row.cat},${row.mer})`;
  for (let m = 12; m >= 0; m--) {
    const asOf = m === 0 ? `${today}T08:00:00Z` : `${day(m - 1, 0)}T20:00:00Z`;
    await tx`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance) values(${workspace},${main.id},${180000 + (12 - m) * 9000},'EUR',${asOf},'synthetic qa observation')`;
    await tx`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance) values(${workspace},${savings.id},${1200000 + (12 - m) * 25000},'EUR',${asOf},'synthetic qa observation')`;
  }
  for (const [name, limit] of [["Groceries", 45000], ["Eating out", 15000], ["Transport", 15800], ["Going out", 20000]])
