  await tx`insert into public.financial_assumptions(workspace_id,account_id,kind,name,amount_minor,currency_code,cadence,starts_on,source,confirmed,enabled) values(${workspace},${main.id},'expense','Spotify Family',-1999,'EUR','monthly',${day(-1, 12)},'recurring_confirmed',true,true)`;
});
console.log("seeded", workspace);
await db.end();

