21	/** Asks the model for friendlier wording; any sentence that alters a number is dropped by the caller's keepsFacts check. */
22	export async function rephraseFindings(model: LanguageModel, findings: Pick<Insight, "key" | "type" | "title" | "detail">[]) {
23	  const { object } = await generateObject({
24	    model, maxRetries: 0, maxOutputTokens: 1500, abortSignal: AbortSignal.timeout(20000),
