// Seeds the QA user's workspace with six months of demo data for eyeballing Home. Undo with: node --env-file=.env scripts/e2e-auth.mjs --reset
import postgres from "postgres";
const db = postgres(process.env.SUPABASE_DB_URL, { ssl: "require", max: 1 });
const [{ id: workspace, owner_id: user }] = await db`select w.id, w.owner_id from public.workspaces w join auth.users u on u.id = w.owner_id where u.email = ${process.env.E2E_USER_EMAIL}`;
const today = new Date().toISOString().slice(0, 10);
const day = (monthsBack, date) => new Date(Date.UTC(+today.slice(0, 4), +today.slice(5, 7) - 1 - monthsBack, date)).toISOString().slice(0, 10);
const ago = hours => new Date(Date.now() - hours * 3600000).toISOString();
await db.begin(async tx => {
  const [main] = await tx`insert into public.accounts(workspace_id,name,currency_code,type) values(${workspace},'N26 Main','EUR','checking') returning id`;
  const [holiday] = await tx`insert into public.accounts(workspace_id,name,currency_code,type) values(${workspace},'Holiday reserve','EUR','savings') returning id`;
  const cats = {}; for (const name of ["Salary", "Groceries", "Eating out", "Transport", "Rent", "Going out", "Subscriptions"]) [cats[name]] = await tx`insert into public.categories(workspace_id,name) values(${workspace},${name}) on conflict (workspace_id,name) do update set name=excluded.name returning id`;
  const merch = {}; for (const name of ["Acme GmbH", "Rewe", "Lidl", "Vapiano", "BVG", "Landlord", "Freelance client", "Spotify"]) [merch[name]] = await tx`insert into public.merchants(workspace_id,name,normalized_name) values(${workspace},${name},${name.toLowerCase()}) on conflict (workspace_id,normalized_name) do update set name=excluded.name returning id`;
  const spotify = [];
  for (let m = 5; m >= 0; m--) {
    const add = async (date, description, amount, cat, mer) => {
      const posted = day(m, date); if (posted > today) return null;
      const [row] = await tx`insert into public.transactions(workspace_id,account_id,posted_on,description,amount_minor,currency_code,status,category_id,merchant_id) values(${workspace},${main.id},${posted},${description},${amount},'EUR','posted',${cats[cat].id},${merch[mer].id}) returning id`;
      return row.id;
    };
    await add(1, "Salary Acme", 420000 + m * 1000, "Salary", "Acme GmbH");
    if (m % 2 === 0) await add(14, "Invoice 42", 60000, "Salary", "Freelance client");
    await add(1, "Rent", -115000, "Rent", "Landlord");
    for (const date of [3, 9, 16, 23]) await add(date, "Rewe", -(8000 + (m === 0 ? 4000 : m * 400) + date * 50), "Groceries", "Rewe");
    await add(12, "Lidl", -4200, "Groceries", "Lidl");
    for (const date of [6, 13, 20]) await add(date, "Vapiano", -(5200 + m * 300), "Eating out", "Vapiano");
    await add(2, "BVG monthly", -5800, "Transport", "BVG");
    await add(18, "Cinema", -3200, "Going out", "Vapiano");
    const charge = await add(12, "Spotify Family", m === 0 ? -1999 : -1799, "Subscriptions", "Spotify");
    if (charge && m <= 2) spotify.push(charge);
  }
  for (let m = 12; m >= 1; m--) {
    const asOf = `${day(m - 1, 0)}T20:00:00Z`;
    await tx`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance) values(${workspace},${main.id},${150000 + (12 - m) * 6000},'EUR',${asOf},'synthetic qa observation')`;
    await tx`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance) values(${workspace},${holiday.id},${1000000 + (12 - m) * 40000},'EUR',${asOf},'synthetic qa observation')`;
  }
  // Today's balances are set by hand, so they show up in History.
  await tx`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance,actor_id,created_at) values(${workspace},${main.id},90000,'EUR',${`${today}T07:00:00Z`},'manual',${user},${ago(26)})`;
  await tx`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance,actor_id,created_at) values(${workspace},${holiday.id},1500000,'EUR',${`${today}T07:00:00Z`},'manual',${user},${ago(50)})`;
  for (const [name, limit] of [["Groceries", 45000], ["Eating out", 15000], ["Transport", 15800], ["Going out", 20000]])
    await tx`insert into public.spending_plans(workspace_id,category_id,currency_code,limit_minor,enabled,rollover,rollover_from) values(${workspace},${cats[name].id},'EUR',${limit},true,false,${day(0, 1)})`;
  const assumption = async (name, amount, date) => (await tx`insert into public.financial_assumptions(workspace_id,account_id,kind,name,amount_minor,currency_code,cadence,starts_on,source,confirmed,enabled) values(${workspace},${main.id},'expense',${name},${amount},'EUR','monthly',${date},'recurring_confirmed',true,true) returning id`)[0].id;
  await assumption("Rent", -115000, day(-1, 1));
  await assumption("Gym", -2990, day(-1, 1));
  const spotifyAssumption = await assumption("Spotify Family", -1999, day(-1, 12));
  const [series] = await tx`insert into public.recurring_series(workspace_id,account_id,label,normalized_label,cadence,currency_code,amount_min_minor,amount_max_minor,occurrences,confidence,status,assumption_id) values(${workspace},${main.id},'Spotify Family','spotify family','monthly','EUR',-1999,-1799,3,90,'confirmed',${spotifyAssumption}) returning id`;
  for (const id of spotify) await tx`insert into public.recurring_series_transactions(series_id,transaction_id,workspace_id) values(${series.id},${id},${workspace})`;
  const [run] = await tx`insert into public.agent_runs(workspace_id,trigger,status,created_at,finished_at) values(${workspace},'manual','completed',${ago(3)},${new Date(Date.now() - 3 * 3600000 + 252000).toISOString()}) returning id`;
  const summaries = { lead: "Merged 6 reports", categorizer: "14 proposals · 2 new rules", recurring: "2 new subscriptions", anomaly: "1 possible duplicate", budget: "1 budget suggestion", forecaster: "Shortfall flagged 1 Nov", writer: "Briefing ready" };
  for (const [index, [agent, summary]] of Object.entries(summaries).entries()) await tx`insert into public.agent_tasks(run_id,workspace_id,agent,position,status,summary) values(${run.id},${workspace},${agent},${index},'done',${summary})`;
  const proposal = (agent, kind, key, title, status, decided) => tx`insert into public.agent_proposals(run_id,workspace_id,agent,kind,conflict_key,title,status,decided_at,result) values(${run.id},${workspace},${agent},${kind},${key},${title},${status},${decided},${status === "accepted" ? tx.json({ href: "/money/organization" }) : null})`;
  await proposal("categorizer", "categorize", "c1", "Categorized 14 transactions as Groceries", "accepted", ago(2.5));
  await proposal("recurring", "recurring", "r1", "Confirmed Spotify Family as a subscription", "accepted", ago(20));
  for (let n = 0; n < 5; n++) await proposal("categorizer", "categorize", `p${n}`, `Proposal ${n + 1}`, "proposed", null);
  await proposal("anomaly", "finding", "f1", "Possible duplicate Rewe charge", "proposed", null);
});
console.log("seeded", workspace);
await db.end();

