  const assumption = async (name, amount, date) => (await tx`insert into public.financial_assumptions(workspace_id,account_id,kind,name,amount_minor,currency_code,cadence,starts_on,source,confirmed,enabled) values(${workspace},${main.id},'expense',${name},${amount},'EUR','monthly',${date},'recurring_confirmed',true,true) returning id`)[0].id;
  await assumption("Rent", -115000, day(-1, 1));
  await assumption("Gym", -2990, day(-1, 1));
  const spotifyAssumption = await assumption("Spotify Family", -1999, day(-1, 12));
  const [series] = await tx`insert into public.recurring_series(workspace_id,account_id,label,normalized_label,cadence,currency_code,amount_min_minor,amount_max_minor,occurrences,confidence,status,assumption_id) values(${workspace},${main.id},'Spotify Family','spotify family','monthly','EUR',-1999,-1799,3,90,'confirmed',${spotifyAssumption}) returning id`;
  for (const id of spotify) await tx`insert into public.recurring_series_transactions(series_id,transaction_id,workspace_id) values(${series.id},${id},${workspace})`;
  const [run] = await tx`insert into public.agent_runs(workspace_id,trigger,status,created_at,finished_at) values(${workspace},'manual','completed',${ago(3)},${new Date(Date.now() - 3 * 3600000 + 252000).toISOString()}) returning id`;
  const summaries = { lead: "Merged 6 reports", categorizer: "14 proposals · 2 new rules", recurring: "2 new subscriptions", anomaly: "1 possible duplicate", budget: "1 budget suggestion", forecaster: "Shortfall flagged 1 Nov", writer: "Briefing ready" };
  for (const [index, [agent, summary]] of Object.entries(summaries).entries()) await tx`insert into public.agent_tasks(run_id,workspace_id,agent,position,status,summary) values(${run.id},${workspace},${agent},${index},'done',${summary})`;
  const proposal = (agent, kind, key, title, status, decided) => tx`insert into public.agent_proposals(run_id,workspace_id,agent,kind,conflict_key,title,status,decided_at,result) values(${run.id},${workspace},${agent},${kind},${key},${title},${status},${decided},${status === "accepted" ? tx.json({ href: "/money/organization" }) : null})`;
  await proposal("categorizer", "categorize", "c1", "Categorized 14 transactions as Groceries", "accepted", ago(2.5));
  await proposal("recurring", "recurring", "r1", "Confirmed Spotify Family as a subscription", "accepted", ago(20));
